const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/workforce-planning/v2/companies/%7Bcompany_id%7D/notification-profiles',
  qs: {
    limit: '10',
    starting_after: '0020107c-77cf-4cc8-b5bf-b5f6e1edfef6',
    starting_before: '7a2d8fcc-bd8e-49df-9cdb-00f55c07bea0'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/workforce-planning/v2/companies/%7Bcompany_id%7D/notification-profiles?limit=10&starting_after=0020107c-77cf-4cc8-b5bf-b5f6e1edfef6&starting_before=7a2d8fcc-bd8e-49df-9cdb-00f55c07bea0"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
